-- Minimal phase-17 contract fixture, not a replacement for staging against the real database.
create schema auth;create schema storage;create schema realtime;create schema extensions;
create role anon;create role authenticated;create role service_role bypassrls;
create function auth.uid() returns uuid language sql stable as $$ select nullif(current_setting('request.jwt.claim.sub',true),'')::uuid $$;
create function auth.role() returns text language sql stable as $$ select nullif(current_setting('request.jwt.claim.role',true),'') $$;
create function realtime.topic() returns text language sql stable as $$ select current_setting('realtime.topic',true) $$;
create table realtime.messages(id bigint,extension text);alter table realtime.messages enable row level security;
create table storage.buckets(id text primary key,name text,public boolean,file_size_limit bigint,allowed_mime_types text[]);
create table storage.objects(id uuid,bucket_id text);alter table storage.objects enable row level security;
create table profiles(id uuid primary key,full_name text,role text,avatar_url text,verification_status text,trust_score numeric,warning_count integer default 0,is_banned boolean default false,latitude numeric,longitude numeric,location_name text);
create table products(id bigint generated by default as identity primary key,seller_id uuid references profiles(id),title text,description text,quantity numeric,price numeric,category text,material text,status text,created_at timestamptz default now(),updated_at timestamptz default now(),current_owner_id uuid,sold_deal_id uuid);
create table product_images(id uuid default gen_random_uuid() primary key,product_id bigint references products(id),image_url text,verification_status text);
create table conversations(id bigint primary key,buyer_id uuid,seller_id uuid);
create table messages(id bigint primary key,sender_id uuid,message text);
create table deal_requests(id uuid default gen_random_uuid() primary key,product_id bigint references products(id),buyer_id uuid references profiles(id),seller_id uuid references profiles(id),deal_code text,status text,agreed_price numeric,is_disputed boolean default false,exchange_code_verified_at timestamptz,exchange_code_hash text,exchange_code_generated_at timestamptz,exchange_code_expires_at timestamptz,exchange_code_attempts integer default 0,buyer_handover_confirmed_at timestamptz,seller_handover_confirmed_at timestamptz,completed_at timestamptz,created_at timestamptz default now(),updated_at timestamptz default now());
create table ownership_events(id uuid default gen_random_uuid() primary key,product_id bigint,deal_id uuid,deal_code text,previous_owner_id uuid,new_owner_id uuid,event_type text default 'ownership_transfer',previous_hash text,event_hash text,created_at timestamptz default now());
create table calls(id uuid default gen_random_uuid() primary key,caller_id uuid,receiver_id uuid,product_id bigint,deal_id uuid,status text,recording_url text,transcript text,risk_score integer default 0,is_diverted boolean default false,started_at timestamptz default now(),answered_at timestamptz,ended_at timestamptz,duration_seconds integer default 0,created_at timestamptz default now());
create table communication_risk_events(id uuid default gen_random_uuid() primary key,call_id uuid,deal_id uuid,conversation_id bigint,reported_user_id uuid,actor_id uuid,risk_type text,risk_score integer,confidence text,snippet_excerpt text,review_status text,admin_notes text,is_demo boolean default false,created_at timestamptz default now());
create table deal_disputes(id uuid default gen_random_uuid() primary key,deal_id uuid,raised_by uuid,reason text,description text,status text default 'OPEN',resolution_notes text,resolved_at timestamptz,created_at timestamptz default now());
create table deal_audit_logs(id uuid default gen_random_uuid() primary key,deal_id uuid,actor_id uuid,event_type text,metadata jsonb,created_at timestamptz default now());
create table deal_notifications(id uuid default gen_random_uuid() primary key,user_id uuid,deal_id uuid,call_id uuid,type text,title text,message text,action_url text,created_at timestamptz default now());
alter table profiles enable row level security;create policy old_profile_read on profiles for select using(true);create policy old_profile_write on profiles for all using(id=auth.uid()) with check(id=auth.uid());
alter table products enable row level security;create policy old_product_read on products for select using(status='approved' or seller_id=auth.uid());create policy old_product_write on products for all using(seller_id=auth.uid()) with check(seller_id=auth.uid());
alter table deal_requests enable row level security;create policy old_deal_read on deal_requests for select using(auth.uid() in(buyer_id,seller_id));create policy old_deal_write on deal_requests for update using(auth.uid() in(buyer_id,seller_id));
alter table calls enable row level security;create policy old_call_read on calls for select using(auth.uid() in(caller_id,receiver_id));
grant usage on schema public,auth,realtime to anon,authenticated,service_role;grant all on all tables in schema public to authenticated,service_role;grant select on all tables in schema public to anon;grant usage,select on all sequences in schema public to authenticated,service_role;
